module abstract_design(
  i_clk,
  i_reset,
  i_wr,
  i_data,
  o_full,
  o_fill,
  i_rd,
  o_data,
  o_empty,
  __ar_const_0,
  __ar_a,
  __ar_en,
  abs_o_data
);
  input i_clk;
  input i_reset;
  input i_wr;
  input [511:0] i_data;
  output o_full;
  output [6:0] o_fill;
  input i_rd;
  output [511:0] o_data;
  output o_empty;
  input [6:0] __ar_const_0;
  output [27:0] __ar_a;
  output [27:0] __ar_en;

  input [511:0] abs_o_data;

  reg [6:0] fill = 7'd0;
  reg [6:0] wr_addr = 7'd0;
  reg [6:0] rd_addr = 7'd0;
  reg empty = 1'b1;

  reg past_valid = 1'b0;
  reg [6:0] past_fill;
  reg past_no_read_nonempty;

  reg a6 = 1'b1;
  reg a7 = 1'b1;
  reg a8 = 1'b1;
  reg a9 = 1'b1;
  reg en6 = 1'b0;
  reg en7 = 1'b0;
  reg en8 = 1'b0;
  reg en9 = 1'b0;

  wire full;
  wire do_write;
  wire do_read;
  wire [6:0] f_fill;

  assign full = fill[6];
  assign do_write = i_wr && !full;
  assign do_read = i_rd && !empty;
  assign f_fill = wr_addr - rd_addr;

  always @(posedge i_clk) begin
    if (i_reset)
      fill <= 7'd0;
    else begin
      case ({do_write, do_read})
        2'b01: fill <= fill - 7'd1;
        2'b10: fill <= fill + 7'd1;
        default: fill <= fill;
      endcase
    end
  end

  always @(posedge i_clk) begin
    if (i_reset)
      wr_addr <= 7'd0;
    else if (do_write)
      wr_addr <= wr_addr + 7'd1;
  end

  always @(posedge i_clk) begin
    if (i_reset)
      rd_addr <= 7'd0;
    else if (do_read)
      rd_addr <= rd_addr + 7'd1;
  end

  always @(posedge i_clk) begin
    if (i_reset)
      empty <= 1'b1;
    else begin
      case ({do_write, do_read})
        2'b01: empty <= (fill <= 7'd1);
        2'b10: empty <= 1'b0;
        default: empty <= empty;
      endcase
    end
  end

  always @(posedge i_clk) begin
    a6 <= empty;
    a7 <= empty;
    a8 <= !empty;
    a9 <= !empty;

    en6 <= past_valid && (f_fill == 7'd0);
    en7 <= past_valid && (f_fill == 7'd0);
    en8 <= past_valid && (f_fill != 7'd0) && (past_fill > 7'd1);
    en9 <= past_valid && (f_fill != 7'd0) && !(past_fill > 7'd1)
           && past_no_read_nonempty;

    past_valid <= 1'b1;
    past_fill <= f_fill;
    past_no_read_nonempty <= !i_rd && (f_fill > 7'd0);
  end

  assign o_full = full;
  assign o_fill = fill;
  assign o_empty = empty;
  assign o_data = abs_o_data;

  assign __ar_a[0] = (f_fill <= 7'd64);
  assign __ar_a[1] = (fill == f_fill);
  assign __ar_a[2] = (full == (f_fill == 7'd64));
  assign __ar_a[3] = (empty == (f_fill == 7'd0));
  assign __ar_a[4] = 1'b1;
  assign __ar_a[5] = 1'b1;
  assign __ar_a[6] = a6;
  assign __ar_a[7] = a7;
  assign __ar_a[8] = a8;
  assign __ar_a[9] = a9;
  assign __ar_a[27:10] = 18'h3ffff;

  assign __ar_en[5:0] = 6'h3f;
  assign __ar_en[6] = en6;
  assign __ar_en[7] = en7;
  assign __ar_en[8] = en8;
  assign __ar_en[9] = en9;
  assign __ar_en[27:10] = 18'h3ffff;
endmodule

